  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to use req.params.id now
    res.json({ message: `Fetching user with ID: ${req.params.id}` });
  }
);
```

#### 3. Implement Security Headers
```javascript
const helmet = require('helmet');

// Add security headers
app.use(helmet());
// Or configure specific headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"]
    }
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' }
}));
```

#### 4. Add Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');

// Apply to all requests
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  standardHeaders: true,
  legacyHeaders: false,
});

app.use('/auth', authLimiter);
```

#### 5. Implement Proper Error Handling
```javascript
// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak stack traces in production
  const status = err.status || 500;
  const message = status === 500 
    ? 'Internal Server Error' 
    : err.message;

  res.status(status).json({
    error: {
      message,
      // Only include details in development
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

#### 6. Add Security-focused Logging
```javascript
const morgan = require('morgan');

// Custom token for user ID in logs
morgan.token('user-id', (req) => {
  return req.user ? req.user.id : '-';
});

// Use combined format with user ID
app.use(morgan(':remote-address :user-id :method :url :status :response-time ms - :res[content-length]'));
```

#### 7. Environment-based Configuration
```javascript
// Configure based on environment
if (process.env.NODE_ENV === 'production') {
  // Production-specific settings
  app.set('trust proxy', 1); // Trust first proxy

  // Ensure secure cookies
  app.use(session({
    cookie: {
      secure: true,
      httpOnly: true,
      sameSite: 'strict'
    }
  }));
}

// Disable powered-by header
